BEGIN;
create temp table assertion_count(n integer);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table test_state(k text primary key,v jsonb);
insert into public.properties(id,org_id,name,address,settings)values('ee220000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Assistant facts SQL fixture','{"city":"Exact city"}','{"private_credential":"must-not-enter-facts"}');
insert into public.property_chatbot_contexts(property_id,status,requires_review,context_markdown,last_generated_at)values('ee220000-0000-4000-8000-000000000001','current',false,'Earlier unreviewed context',clock_timestamp());
insert into public.documents(property_id,content,metadata)
 select'ee220000-0000-4000-8000-000000000001',case when n=25 then E'Ordinary policy without FAQ labels.\r\n'||repeat('x',1800)||'THE COMPLETE END 🏡'else'Exact source '||n end,jsonb_build_object('title','Source fixture '||n,'source','pasted_text')from generate_series(1,25)n;
insert into public.property_units(property_id,org_id,canonical_key,unit_type,rent_min,bedrooms,active,review_status)values('ee220000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','approved-fixture','Approved zero price',0,0,true,'approved'),('ee220000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','pending-fixture','Pending price',9999,1,true,'pending');
create function pg_temp.prepare_input()returns jsonb language sql as $$select jsonb_build_object('operation','prepare','expectedDraftId',v->'workspace'->'latest_version_id','expectedSourceHash',v->>'sourceHash','expectedContextHash',v->>'contextHash','markdown',null,'reason','Review exact complete synthetic property facts')from(select public.read_assistant_facts('ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111')v)x$$;
create function pg_temp.release_input(op text default'publish')returns jsonb language sql as $$select jsonb_build_object('operation',op,'versionId',v->'selected'->>'id','expectedDraftId',v->'workspace'->'latest_version_id','expectedActiveId',v->'workspace'->'active_version_id','expectedReleaseId',v->'workspace'->'last_release_id','expectedContextHash',v->>'contextHash','markdownHash',v->'selected'->>'markdown_hash','confirmed',true,'reason','Review exact synthetic facts publication')from(select public.read_assistant_facts('ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111')v)x$$;
insert into test_state values('input1',pg_temp.prepare_input());
insert into test_state values('prepared',public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000010','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v from test_state where k='input1')));
select pg_temp.check_it(v->>'state'='saved'and v->'published'='false','complete draft saved privately')from test_state where k='prepared';
select pg_temp.check_it(public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000010','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v from test_state where k='input1'))->>'state'='replayed','same preparation recovers exact version');
select pg_temp.check_it(public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000010','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v||'{"reason":"different intent"}'from test_state where k='input1'))->>'state'='request_conflict','changed request is held');
select pg_temp.check_it((select context_markdown from public.property_chatbot_contexts where property_id='ee220000-0000-4000-8000-000000000001')='Earlier unreviewed context','draft does not replace legacy context');
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'state'='legacy','preparation does not invent adoption');
select pg_temp.check_it((select position('THE COMPLETE END 🏡'in markdown)>0 and position(E'\r\n'in markdown)>0 from public.assistant_fact_versions where id='ee220000-0000-4000-8000-000000000010'),'all ordinary source text and CRLF retained beyond old excerpt limits');
select pg_temp.check_it((select jsonb_array_length(source_snapshot->'documents')=25 from public.assistant_fact_versions where id='ee220000-0000-4000-8000-000000000010'),'more than 24 chunks retained');
select pg_temp.check_it((select position('Approved zero price'in markdown)>0 and position('Pending price'in markdown)=0 from public.assistant_fact_versions where id='ee220000-0000-4000-8000-000000000010'),'only explicitly eligible floorplans enter serving text');
select pg_temp.check_it((select position('must-not-enter-facts'in source_snapshot::text)=0 from public.assistant_fact_versions where id='ee220000-0000-4000-8000-000000000010'),'internal settings do not enter facts');
insert into test_state values('release1',pg_temp.release_input());
insert into test_state values('published',public.release_assistant_facts('ee220000-0000-4000-8000-000000000020','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v from test_state where k='release1')));
select pg_temp.check_it(v->'published'='true','reviewed facts published')from test_state where k='published';
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'state'='ready','current exact facts can serve');
select pg_temp.check_it(position('THE COMPLETE END 🏡'in public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'contextMarkdown')>0,'ordinary source policy actually reaches serving text');
select pg_temp.check_it(public.release_assistant_facts('ee220000-0000-4000-8000-000000000020','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v from test_state where k='release1'))->>'state'='replayed','publication lost reply replays');
select pg_temp.check_it((select count(*)from public.property_chatbot_context_revisions where property_id='ee220000-0000-4000-8000-000000000001')=1,'publication context revision saved once');
do $$begin begin update public.property_chatbot_contexts set context_markdown='Unrecorded replacement',status='current'where property_id='ee220000-0000-4000-8000-000000000001';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'legacy context overwrite blocked');end;end$$;
do $$begin begin update public.assistant_fact_versions set markdown='Changed original'where id='ee220000-0000-4000-8000-000000000010';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'draft history immutable');end;end$$;
update public.documents set content=content||' NEW SOURCE CHANGE'where property_id='ee220000-0000-4000-8000-000000000001'and metadata->>'title'='Source fixture 1';
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'reason'='sources_changed','content-only legacy mutation with no stale marker blocks serving');
select pg_temp.check_it(not(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')?'contextMarkdown'),'withheld read exposes no earlier serving text');
select pg_temp.check_it(public.release_assistant_facts(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input())->>'state'='sources_changed','old source snapshot cannot publish against new source');
insert into test_state values('prepared2',public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000011','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.prepare_input()));
insert into test_state select'editInput',jsonb_build_object('operation','edit','expectedDraftId',v->'workspace'->'latest_version_id','expectedSourceHash',v->>'sourceHash','expectedContextHash',v->>'contextHash','markdown',E'Exact reviewed correction.\r\nConfirmed policy: dogs are welcome.','reason','Reviewed manual correction with retained full evidence')from(select public.read_assistant_facts('ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111')v)x;
insert into test_state values('edited',public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000012','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v from test_state where k='editInput')));
select pg_temp.check_it(v->>'state'='saved'and v->'published'='false','manual correction is a private draft')from test_state where k='edited';
select pg_temp.check_it((select source_snapshot=(select source_snapshot from public.assistant_fact_versions where id='ee220000-0000-4000-8000-000000000011')from public.assistant_fact_versions where id='ee220000-0000-4000-8000-000000000012'),'manual correction retains full exact source evidence');
select pg_temp.check_it(public.save_assistant_fact_draft(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v from test_state where k='editInput'))->>'state'='draft_changed','concurrent draft correction held');
insert into test_state values('published2',public.release_assistant_facts('ee220000-0000-4000-8000-000000000021','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input()));
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'contextMarkdown'=E'Exact reviewed correction.\r\nConfirmed policy: dogs are welcome.','exact reviewed manual facts serve');
insert into test_state values('withdrawn',public.release_assistant_facts('ee220000-0000-4000-8000-000000000022','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input('withdraw')));
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'reason'='withdrawn','withdrawal never falls back to legacy or earlier version');
select pg_temp.check_it((select count(*)from public.assistant_fact_versions where property_id='ee220000-0000-4000-8000-000000000001')=3,'withdrawal retains original and corrected drafts');
insert into test_state values('repub',public.release_assistant_facts('ee220000-0000-4000-8000-000000000023','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input()));
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'state'='ready','explicit republication restores exact reviewed facts');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee220000-0000-4000-8000-000000000010','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Recover already saved facts'))->>'decisionDomain'='assistant_facts','unused-request cancellation recovers a saved facts decision');
update public.profiles set role=null where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(public.save_assistant_fact_draft(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"operation":"prepare"}')->>'state'='forbidden','current manager role required');
update public.profiles set role='admin'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(public.read_assistant_facts('ee220000-0000-4000-8000-000000000001','ffffffff-ffff-4fff-8fff-ffffffffffff')->>'state'='forbidden','unknown actor cannot read private sources');
select pg_temp.check_it(not has_function_privilege('authenticated','public.read_serving_assistant_facts(uuid)','EXECUTE')and not has_table_privilege('authenticated','public.assistant_fact_versions','SELECT'),'private facts and runtime RPC service-only');
insert into test_state values('beforeRollback',public.assistant_current_context('ee220000-0000-4000-8000-000000000001'));
create function pg_temp.reject_fact_event()returns trigger language plpgsql as $$begin if new.action='knowledge.facts.published'then raise exception 'synthetic history failure';end if;return new;end$$;
create trigger fixture_fact_event_failure before insert on public.shared_action_events for each row execute function pg_temp.reject_fact_event();
do $$begin begin perform public.release_assistant_facts(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input());raise exception 'event failure ignored'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'history failure rolls publication back');end;end$$;
drop trigger fixture_fact_event_failure on public.shared_action_events;
select pg_temp.check_it(public.assistant_current_context('ee220000-0000-4000-8000-000000000001')=(select v from test_state where k='beforeRollback'),'failed publication preserves exact prior context');

insert into test_state values('beforeStaleInput',pg_temp.release_input());
update public.property_chatbot_contexts set status='stale',stale_at=clock_timestamp(),version=version+1 where property_id='ee220000-0000-4000-8000-000000000001';
select pg_temp.check_it(public.release_assistant_facts(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v from test_state where k='beforeStaleInput'))->>'state'='context_changed','concurrent context invalidation fences reviewed publication');
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'reason'='review_required','stale current context withheld');
insert into test_state values('reviewedAgain',public.release_assistant_facts(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input()));
insert into public.knowledge_sources(id,property_id,source_type,source_name,status,last_synced_at)values('ee220000-0000-4000-8000-000000000099','ee220000-0000-4000-8000-000000000001','website','Old recorded website','completed',clock_timestamp()-interval'8 days');
insert into test_state values('oldWebsiteDraft',public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000014','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.prepare_input()));
insert into test_state values('oldWebsitePublication',public.release_assistant_facts(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input()));
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'freshnessReviewReason'='website_freshness_review_due' and public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'state'='ready','old website observation remains dated but does not revoke approved facts');
update public.knowledge_sources set last_synced_at=clock_timestamp()where id='ee220000-0000-4000-8000-000000000099';
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'reason'='sources_changed','fresh website receipt still needs facts rereview');
insert into test_state values('currentWebsiteDraft',public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000015','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.prepare_input()));
insert into test_state values('currentWebsitePublication',public.release_assistant_facts(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input()));
select pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'state'='ready','fresh reviewed source set can serve');
insert into test_state values('cancelInput',pg_temp.prepare_input());
insert into test_state values('cancelUnused',public.cancel_unused_knowledge_decision('ee220000-0000-4000-8000-000000000090','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Cancel unused synthetic facts decision')));
select pg_temp.check_it(public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000090','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',(select v from test_state where k='cancelInput'))->>'state'='decision_cancelled','cancelled facts request cannot arrive late');
do $$declare oid uuid:=gen_random_uuid();begin
 insert into public.organizations(id,name)values(oid,'Assistant facts synthetic transfer');
 update public.assistant_fact_workspaces set org_id=oid where property_id='ee220000-0000-4000-8000-000000000001';
 perform pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'reason'='property_scope_changed','mismatched property organization cannot inherit prior publication authority');
 perform pg_temp.check_it(public.read_assistant_facts('ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111')->>'state'='forbidden','mismatched workspace cannot disclose source history');
 update public.assistant_fact_workspaces set org_id='22222222-2222-2222-2222-222222222222'where property_id='ee220000-0000-4000-8000-000000000001';
end$$;

do $$declare mid uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();release_id uuid:=gen_random_uuid();claim jsonb;result jsonb;receipt jsonb;content text:='A managed policy reaches the reviewed assistant.';digest text;begin
 digest:=encode(extensions.digest(content,'sha256'),'hex');
 perform public.save_knowledge_material(mid,'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',null,'previousVersionId',null,'title','Managed knowledge fixture','content',content,'reason','Retain managed source for integration verification'));
 perform pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'state'='ready','private source draft does not invalidate published facts');
 perform public.begin_knowledge_search(sid,'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',mid,'versionId',mid,'contentHash',digest,'confirmed',true,'reason','Synthetic exact preparation fixture'),jsonb_build_object('model','text-embedding-3-small','dimensions',1536,'recipe','lossless-utf8-4096-v1','chunks',jsonb_build_array(content),'contentHash',digest));
 claim:=public.claim_knowledge_search(sid);
 receipt:=jsonb_build_object('status','received','providerRequestId','synthetic-only-no-provider-call','response',jsonb_build_object('model','text-embedding-3-small','usage',jsonb_build_object('total_tokens',12),'data',jsonb_build_array(jsonb_build_object('index',0,'embedding',(select jsonb_agg(case when n=1 then 1 else 0 end order by n)from generate_series(1,1536)n)))));
 perform public.record_knowledge_search_result(sid,(claim->>'claimToken')::uuid,receipt);
 perform public.validate_knowledge_search(sid,(select result_hash from public.knowledge_embedding_requests where id=sid));
 result:=public.release_knowledge_material(release_id,'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',mid,'versionId',mid,'expectedLatestVersionId',mid,'expectedActiveVersionId',null,'expectedReleaseId',null,'resultHash',(select result_hash from public.knowledge_embedding_requests where id=sid),'operation','publish','confirmed',true,'reason','Publish exact managed knowledge fixture'));
 perform pg_temp.check_it(result->>'state'='saved','managed source publishes after facts adoption');
 perform pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'state'='withheld','knowledge publication invalidates adopted assistant facts');
 perform public.save_assistant_fact_draft(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.prepare_input());
 perform public.release_assistant_facts(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input());
 perform pg_temp.check_it(position(content in public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'contextMarkdown')>0,'reviewed managed source actually reaches Luma facts');
 result:=public.release_knowledge_material(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',mid,'versionId',mid,'expectedLatestVersionId',mid,'expectedActiveVersionId',mid,'expectedReleaseId',release_id,'resultHash',null,'operation','withdraw','confirmed',true,'reason','Withdraw exact managed source fixture'));
 perform pg_temp.check_it(result->>'state'='saved','managed source withdraws after facts adoption');
 perform pg_temp.check_it(public.read_serving_assistant_facts('ee220000-0000-4000-8000-000000000001')->>'state'='withheld','source withdrawal cannot leave old assistant facts serving');
 perform public.save_assistant_fact_draft(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.prepare_input());
end$$;
insert into public.documents(property_id,content,metadata)select'ee220000-0000-4000-8000-000000000001','Complete additional source text '||n,jsonb_build_object('title','Complete source '||n)from generate_series(1,1001)n;
insert into test_state values('large',public.save_assistant_fact_draft('ee220000-0000-4000-8000-000000000013','ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.prepare_input()));
select pg_temp.check_it(v->>'state'='saved'and v->'withinBudget'='false','large complete draft retained without silent truncation')from test_state where k='large';
select pg_temp.check_it((select jsonb_array_length(source_snapshot->'documents')=1026 and position('Complete additional source text 1001'in markdown)>0 from public.assistant_fact_versions where id='ee220000-0000-4000-8000-000000000013'),'full source set exceeds old REST and excerpt caps');
select pg_temp.check_it(public.release_assistant_facts(gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',pg_temp.release_input())->>'state'='publication_too_large','oversize publication explicitly held');
insert into public.assistant_fact_versions(id,property_id,org_id,actor_id,origin,source_snapshot,source_hash,markdown,markdown_hash)
 select gen_random_uuid(),'ee220000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','edited','{}',repeat('a',64),'History fixture',repeat('b',64)from generate_series(1,1001)n;
insert into test_state values('history',public.read_assistant_facts('ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"versions","offset":1000}'));
select pg_temp.check_it(v->>'total'='1009'and jsonb_array_length(v->'items')=9 and v->'nextOffset'='null','all retained facts versions remain reachable past REST cap')from test_state where k='history';
select pg_temp.check_it(public.read_assistant_facts('ee220000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"versions","expectedHash":"old"}')->>'state'='history_changed','changed history held');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee220000-0000-4000-8000-000000000001'and(request::text||result::text)like'%dogs are welcome%'),'activity excludes private fact content');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee220000-0000-4000-8000-000000000001'and training_eligible),'facts decisions do not authorize training');
select pg_temp.check_it(not exists(select 1 from public.shared_jobs where property_id='ee220000-0000-4000-8000-000000000001'and domain<>'knowledge.embedding'),'facts preparation adds no model job');
select n as passed_assertions from assertion_count;
ROLLBACK;
